'use strict';

// MODULES //

var isNumberOrComplexLike = require( '@stdlib/assert-is-number-or-complex-like' ).isPrimitive;
var ZERO = require( '@stdlib/constants-complex64-zero' );
var factory = require( '@stdlib/ndarray-tensor0d-complex-ctor-factory' );


// MAIN //

/**
* Returns a single-precision complex floating-point zero-dimensional ndarray.
*
* @name Complex64Tensor0D
* @type {Function}
* @param {(ComplexLike|number|ArrayBuffer)} [value] - scalar, real component, or buffer
* @param {(NonNegativeInteger|number)} [arg1] - byte offset or imaginary component
* @param {Options} [options] - function options
* @param {boolean} [options.readonly=false] - boolean indicating whether to return a read-only ndarray
* @param {string} [options.order='row-major'] - memory layout (either row-major or column-major)
* @throws {TypeError} first argument must be either a number, complex number, buffer, or options object
* @throws {TypeError} must provide valid options
* @returns {ndarray} zero-dimensional ndarray
*
* @example
* var arr = new Complex64Tensor0D();
* // returns <ndarray>[ <Complex64>[ 0.0, 0.0 ] ]
*
* @example
* var arr = new Complex64Tensor0D( 1.0 );
* // returns <ndarray>[ <Complex64>[ 1.0, 0.0 ] ]
*
* @example
* var arr = new Complex64Tensor0D( 1.0, 2.0 );
* // returns <ndarray>[ <Complex64>[ 1.0, 2.0 ] ]
*
* @example
* var Complex64 = require( '@stdlib/complex-float32-ctor' );
*
* var arr = new Complex64Tensor0D( new Complex64( 3.0, 4.0 ) );
* // returns <ndarray>[ <Complex64>[ 3.0, 4.0 ] ]
*
* @example
* var ArrayBuffer = require( '@stdlib/array-buffer' );
*
* var buf = new ArrayBuffer( 16 );
* var arr = new Complex64Tensor0D( buf );
* // returns <ndarray>[ <Complex64>[ 0.0, 0.0 ] ]
*
* @example
* var ArrayBuffer = require( '@stdlib/array-buffer' );
*
* var buf = new ArrayBuffer( 32 );
* var arr = new Complex64Tensor0D( buf, 16 );
* // returns <ndarray>[ <Complex64>[ 0.0, 0.0 ] ]
*/
var Complex64Tensor0D = factory( 'complex64', ZERO, isNumberOrComplexLike );


// EXPORTS //

module.exports = Complex64Tensor0D;
